        return []

    if demands is None:
        demands = [0] * n
    if coords is None:
        coords = [(i, 0) for i in range(n)]
    if capacity is None:
        total = 0
        for i in range(n):
            if i != depot:
                total += demands[i]
        capacity = total if total > 0 else 1

    customers = [i for i in range(n) if i != depot]

    def dist2(a, b):
        ax, ay = coords[a]
        bx, by = coords[b]
        dx = ax - bx
        dy = ay - by
        return dx * dx + dy * dy

    def route_load(route):
        s = 0
        for c in route:
            s += demands[c]
        return s

    def route_cost(route):
        if not route:
            return 0
        c = dist2(depot, route[0]) + dist2(route[-1], depot)
        for i in range(len(route) - 1):
            c += dist2(route[i], route[i + 1])
        return c

    # Constructive phase: sweep by angle-like lexicographic key, then nearest feasible
    def sort_key(c):
        x, y = coords[c]
        dx = x - coords[depot][0]
        dy = y - coords[depot][1]
        q = 0
        if dy < 0:
            q += 2
        if dx < 0:
            q += 1
        return (q, abs(dy) * 1000000 // (abs(dx) + abs(dy) + 1), dist2(depot, c), x, y, c)

    unassigned = sorted(customers, key=sort_key)
    routes = []

    while unassigned:
        # seed: highest-demand among feasible, otherwise first
        seed_idx = -1
        best_seed = None
        for i, c in enumerate(unassigned):
            d = demands[c]
            if d <= capacity:
                key = (d, dist2(depot, c), c)
                if best_seed is None or key > best_seed:
                    best_seed = key
                    seed_idx = i
        if seed_idx == -1:
            seed_idx = 0
        route = [unassigned.pop(seed_idx)]
        cap_left = capacity - demands[route[0]]

        while unassigned:
            last = route[-1]
            best_i = -1
            best_score = None
            for i, c in enumerate(unassigned):
                d = demands[c]
                if d > cap_left:
                    continue
                score = (dist2(last, c), -d, dist2(depot, c), c)
                if best_score is None or score < best_score:
                    best_score = score
                    best_i = i
            if best_i == -1:
                break
            c = unassigned.pop(best_i)
            route.append(c)
            cap_left -= demands[c]

        routes.append(route)

    # Merge/split cleanup to ensure capacity and determinism
    repaired = []
    for r in routes:
        cur = []
        load = 0
        for c in r:
            d = demands[c]
            if cur and load + d > capacity:
                repaired.append(cur)
                cur = [c]
                load = d
            else:
                cur.append(c)
                load += d
        if cur:
            repaired.append(cur)
    routes = repaired

    def best_insertion_pos(route, c):
        if not route:
            return 0, 2 * dist2(depot, c)
        best_pos = 0
        best_delta = dist2(depot, c) + dist2(c, route[0]) - dist2(depot, route[0])
        for i in range(1, len(route)):
            delta = dist2(route[i - 1], c) + dist2(c, route[i]) - dist2(route[i - 1], route[i])
            if delta < best_delta:
                best_delta = delta
                best_pos = i
        end_delta = dist2(route[-1], c) + dist2(c, depot) - dist2(route[-1], depot)
        if end_delta < best_delta:
            best_delta = end_delta
            best_pos = len(route)
        return best_pos, best_delta

    # Local improvement: relocate and 2-opt
    improved = True
    while improved:
        improved = False

        # relocate
        best = None
        best_gain = 0
        for i in range(len(routes)):
            ri = routes[i]
            load_i = route_load(ri)
            for p, c in enumerate(ri):
                dc = demands[c]
                if len(ri) == 1:
                    rem = -2 * dist2(depot, c)
                else:
                    left = depot if p == 0 else ri[p - 1]
                    right = depot if p == len(ri) - 1 else ri[p + 1]
                    rem = dist2(left, right) - dist2(left, c) - dist2(c, right)
                for j in range(len(routes)):
                    if i == j:
                        continue
                    rj = routes[j]
                    if route_load(rj) + dc > capacity:
                        continue
                    pos, ins = best_insertion_pos(rj, c)
                    gain = rem + ins
                    if gain < best_gain:
                        best_gain = gain
                        best = (i, p, j, pos, c)
        if best is not None:
            i, p, j, pos, c = best
            routes[i].pop(p)
            routes[j].insert(pos, c)
            improved = True
            continue

        # 2-opt within routes
        for i in range(len(routes)):
            r = routes[i]
            if len(r) < 4:
                continue
            best_a = -1
            best_b = -1
            best_delta = 0
            for a in range(len(r) - 2):
                left = depot if a == 0 else r[a - 1]
                for b in range(a + 2, len(r)):
                    right = depot if b == len(r) - 1 else r[b + 1]
                    delta = dist2(left, r[b]) + dist2(r[a], right) - dist2(left, r[a]) - dist2(r[b], right)
                    if delta < best_delta:
                        best_delta = delta
                        best_a = a
                        best_b = b
            if best_a != -1:
                r[best_a:best_b + 1] = r[best_a:best_b + 1][::-1]
                improved = True
                break

    # Final validation/repair: ensure every customer exactly once
    seen = {}
    final_routes = []
    for r in routes:
        nr = []
        load = 0
        for c in r:
            if c == depot or seen.get(c, False):
                continue
            if load + demands[c] <= capacity:
                seen[c] = True
                nr.append(c)
                load += demands[c]
        if nr:
            final_routes.append(nr)

    missing = [c for c in customers if not seen.get(c, False)]
    for c in missing:
        placed = False
        for r in final_routes:
            if route_load(r) + demands[c] <= capacity:
                r.append(c)
                placed = True
                break
        if not placed:
            final_routes.append([c])

    # remove any accidental empties
    final_routes = [r for r in final_routes if r]
    return final_routes
